theorem ofBasedPath_mem_sheet_iff {U : Set X} {hxU : x ∈ U}
    {q : Path.Homotopic.Quotient x₀ x} {α : BasedPath x₀} :
    ofBasedPath x₀ α ∈ sheet U hxU q ↔ α ∈ basedPathSheet U hxU q

def fundamentalGroupMulEquiv (hp : p ≠ 0) {x : AddCircle p}
    (e : ((↑) : ℝ → AddCircle p) ⁻¹' {x}) :
    FundamentalGroup (AddCircle p) x ≃* Multiplicative ℤ

lemma fundamentalGroupMulEquiv_eq_one_iff (hp : p ≠ 0) {x : AddCircle p}
    (e : ((↑) : ℝ → AddCircle p) ⁻¹' {x}) (γ : FundamentalGroup (AddCircle p) x) :
    fundamentalGroupMulEquiv p hp e γ = 1 ↔ (AddCircle.isCoveringMap_coe p).monodromy γ e = e

def deckEquivFiberOfSurjective [PreconnectedSpace E] (hp : IsCoveringMap p)
    (e : p ⁻¹' {b}) (hsurj : Function.Surjective fun φ : Deck p => φ • e) :
